import React, { useState, useEffect } from 'react';
import { addCamera } from '../services/api';
import { useApp } from '../context/AppContext';

export default function AddCameraModal({ onClose }) {
  const { refreshCameras } = useApp();
  const [loading,     setLoading]     = useState(false);
  const [detecting,   setDetecting]   = useState(false);
  const [error,       setError]       = useState('');
  const [success,     setSuccess]     = useState('');
  const [webcams,     setWebcams]     = useState([]);

  const [form, setForm] = useState({
    name:     '',
    source:   '',
    location: ''
  });

  const [sourceType, setSourceType] = useState('none');
  const [customUrl,  setCustomUrl]  = useState('');

  // ── Auto-detect webcams on open ─────────────────────────────
  useEffect(() => {
    detectWebcams();
  }, []);

  const detectWebcams = async () => {
    setDetecting(true);
    try {
      const res = await fetch('http://localhost:8000/cameras/detect-webcams');
      if (res.ok) {
        const data = await res.json();
        setWebcams(data.webcams || []);
      }
    } catch {
      // Backend detect endpoint not available — use manual list
      setWebcams([{ index: 0, label: 'Webcam 0 (Default)' }]);
    } finally {
      setDetecting(false);
    }
  };

  const handleSourceType = (val) => {
    setSourceType(val);
    setError('');
    if (val === 'none')   setForm(f => ({ ...f, source: '' }));
    else if (val === 'rtsp')   setForm(f => ({ ...f, source: '' }));
    else if (val === 'http')   setForm(f => ({ ...f, source: '' }));
    else if (val === 'custom') setForm(f => ({ ...f, source: customUrl }));
    else                       setForm(f => ({ ...f, source: val })); // webcam index
  };

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = async () => {
    if (!form.name.trim())   return setError('Camera name is required');
    if (!form.source.trim()) return setError('Please select a camera source');

    setLoading(true);
    try {
      await addCamera({
        name:     form.name.trim(),
        source:   form.source.trim(),
        location: form.location.trim() || 'Unknown'
      });
      setSuccess('Camera added successfully!');
      await refreshCameras();
      setTimeout(() => onClose(), 1200);
    } catch (err) {
      setError(err.response?.data?.detail || 'Failed to add camera');
    } finally {
      setLoading(false);
    }
  };

  // ── Styles ───────────────────────────────────────────────────
  const overlay = {
    position: 'fixed', inset: 0,
    background: 'rgba(0,0,0,.8)',
    display: 'flex', alignItems: 'center',
    justifyContent: 'center', zIndex: 1000
  };
  const modal = {
    background: '#111827', border: '1px solid #1e2d47',
    borderRadius: 12, padding: 24,
    width: 440, maxWidth: '95vw',
    maxHeight: '90vh', overflowY: 'auto'
  };
  const labelStyle = {
    fontSize: 11, fontWeight: 600,
    color: '#94a3b8', marginBottom: 5,
    display: 'block', textTransform: 'uppercase',
    letterSpacing: '.5px'
  };
  const inputStyle = {
    width: '100%', background: '#0a0e1a',
    border: '1px solid #1e2d47', borderRadius: 6,
    padding: '8px 12px', color: '#e2e8f0',
    fontSize: 12, outline: 'none', marginBottom: 14,
    boxSizing: 'border-box'
  };
  const optionBtn = (active, color = '#3b82f6') => ({
    flex: 1, padding: '8px 6px', borderRadius: 6,
    border: `1px solid ${active ? color : '#1e2d47'}`,
    background: active ? `${color}22` : '#0a0e1a',
    color: active ? color : '#64748b',
    fontSize: 10, fontWeight: 600,
    cursor: 'pointer', textAlign: 'center',
    transition: 'all .15s'
  });

  return (
    <div style={overlay} onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={modal}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20 }}>
          <div>
            <h2 style={{ fontSize: 16, fontWeight: 700, color: '#fff', margin: 0 }}>
              Add New Camera
            </h2>
            <p style={{ fontSize: 11, color: '#64748b', margin: '4px 0 0' }}>
              Connect a webcam or IP stream to the system
            </p>
          </div>
          <button
            onClick={onClose}
            style={{ background: 'none', border: 'none', color: '#64748b', fontSize: 20, cursor: 'pointer' }}
          >✕</button>
        </div>

        {/* Camera Name */}
        <label style={labelStyle}>Camera Name *</label>
        <input
          style={inputStyle}
          name="name"
          placeholder="e.g. Main Gate, Parking, Office"
          value={form.name}
          onChange={handleChange}
        />

        {/* Source Type Selector */}
        <label style={labelStyle}>
          Source Type *
          {detecting && <span style={{ color: '#64748b', fontWeight: 400, marginLeft: 6 }}>Detecting...</span>}
        </label>

        {/* None option */}
        <div
          onClick={() => handleSourceType('none')}
          style={{
            padding: '10px 14px', borderRadius: 6, marginBottom: 6, cursor: 'pointer',
            border: `1px solid ${sourceType === 'none' ? '#253550' : '#1e2d47'}`,
            background: sourceType === 'none' ? '#151d2e' : '#0a0e1a',
            display: 'flex', alignItems: 'center', gap: 10
          }}
        >
          <span style={{ fontSize: 16 }}>🚫</span>
          <div>
            <div style={{ fontSize: 11, fontWeight: 600, color: sourceType === 'none' ? '#94a3b8' : '#64748b' }}>
              None selected
            </div>
            <div style={{ fontSize: 9, color: '#64748b' }}>Choose a source below</div>
          </div>
        </div>

        {/* Webcam options */}
        {webcams.length > 0 && (
          <>
            <div style={{ fontSize: 10, color: '#64748b', marginBottom: 5, marginTop: 6 }}>
              📷 DETECTED WEBCAMS
            </div>
            {webcams.map((cam) => (
              <div
                key={cam.index}
                onClick={() => handleSourceType(String(cam.index))}
                style={{
                  padding: '10px 14px', borderRadius: 6, marginBottom: 6,
                  cursor: 'pointer',
                  border: `1px solid ${sourceType === String(cam.index) ? '#3b82f6' : '#1e2d47'}`,
                  background: sourceType === String(cam.index) ? '#1e3a5f' : '#0a0e1a',
                  display: 'flex', alignItems: 'center', gap: 10
                }}
              >
                <span style={{ fontSize: 18 }}>📷</span>
                <div>
                  <div style={{ fontSize: 11, fontWeight: 600, color: sourceType === String(cam.index) ? '#60a5fa' : '#e2e8f0' }}>
                    Webcam {cam.index}
                    {cam.index === 0 && <span style={{ fontSize: 9, color: '#22c55e', marginLeft: 6 }}>● Available</span>}
                  </div>
                  <div style={{ fontSize: 9, color: '#64748b' }}>Index {cam.index} — USB / Built-in camera</div>
                </div>
                {sourceType === String(cam.index) && (
                  <span style={{ marginLeft: 'auto', color: '#60a5fa', fontSize: 14 }}>✓</span>
                )}
              </div>
            ))}
          </>
        )}

        {/* IP Stream options */}
        <div style={{ fontSize: 10, color: '#64748b', marginBottom: 5, marginTop: 8 }}>
          🌐 IP STREAM
        </div>
        <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
          {[
            { val: 'rtsp',   label: '📡 RTSP',  hint: 'rtsp://192.168.x.x/stream' },
            { val: 'http',   label: '🌐 HTTP',  hint: 'http://192.168.x.x/video'  },
            { val: 'custom', label: '⚙ Custom', hint: 'Any URL or device path'    },
          ].map(opt => (
            <div
              key={opt.val}
              onClick={() => handleSourceType(opt.val)}
              style={optionBtn(sourceType === opt.val)}
            >
              {opt.label}
            </div>
          ))}
        </div>

        {/* URL input for IP streams */}
        {['rtsp', 'http', 'custom'].includes(sourceType) && (
          <>
            <label style={labelStyle}>Stream URL</label>
            <input
              style={inputStyle}
              placeholder={
                sourceType === 'rtsp'   ? 'rtsp://admin:pass@192.168.1.100:554/stream' :
                sourceType === 'http'   ? 'http://192.168.1.100:8080/video' :
                'Enter any source URL or device path'
              }
              value={form.source}
              onChange={e => {
                setCustomUrl(e.target.value);
                setForm(f => ({ ...f, source: e.target.value }));
              }}
            />
          </>
        )}

        {/* Location */}
        <label style={labelStyle}>Location (optional)</label>
        <input
          style={inputStyle}
          name="location"
          placeholder="e.g. Main Gate, Parking Lot, Office"
          value={form.location}
          onChange={handleChange}
        />

        {/* Preview */}
        <div style={{
          background: '#0a0e1a', border: '1px solid #1e2d47',
          borderRadius: 6, padding: '10px 12px', marginBottom: 14
        }}>
          <div style={{ fontSize: 10, color: '#64748b', marginBottom: 5, fontWeight: 600 }}>
            PREVIEW
          </div>
          <div style={{ fontSize: 11, color: '#e2e8f0', lineHeight: 1.8 }}>
            <span style={{ color: '#64748b' }}>Name:     </span>
            {form.name     || <span style={{ color: '#2a3a50' }}>—</span>}<br />
            <span style={{ color: '#64748b' }}>Source:   </span>
            {form.source   || <span style={{ color: '#2a3a50' }}>—</span>}<br />
            <span style={{ color: '#64748b' }}>Location: </span>
            {form.location || <span style={{ color: '#2a3a50' }}>Unknown</span>}
          </div>
        </div>

        {/* Error / Success */}
        {error && (
          <div style={{
            background: '#450a0a', border: '1px solid #7f1d1d',
            borderRadius: 6, padding: '8px 12px',
            marginBottom: 12, fontSize: 11, color: '#f87171'
          }}>
            ⚠ {error}
          </div>
        )}
        {success && (
          <div style={{
            background: '#0d2010', border: '1px solid #166534',
            borderRadius: 6, padding: '8px 12px',
            marginBottom: 12, fontSize: 11, color: '#4ade80'
          }}>
            ✓ {success}
          </div>
        )}

        {/* Buttons */}
        <div style={{ display: 'flex', gap: 8 }}>
          <button
            onClick={onClose}
            style={{
              flex: 1, background: '#151d2e',
              border: '1px solid #1e2d47', color: '#94a3b8',
              padding: '9px', borderRadius: 6,
              fontSize: 12, fontWeight: 600, cursor: 'pointer'
            }}
          >
            Cancel
          </button>
          <button
            onClick={handleSubmit}
            disabled={loading || sourceType === 'none'}
            style={{
              flex: 2,
              background: (loading || sourceType === 'none') ? '#1e2d47' : '#3b82f6',
              border: 'none', color: (loading || sourceType === 'none') ? '#64748b' : '#fff',
              padding: '9px', borderRadius: 6,
              fontSize: 12, fontWeight: 700,
              cursor: (loading || sourceType === 'none') ? 'not-allowed' : 'pointer'
            }}
          >
            {loading ? '⏳ Adding...' : '+ Add Camera'}
          </button>
        </div>

      </div>
    </div>
  );
}
